package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type MultiSet struct {
	data []int
}

func NewMultiSet(capacity int) *MultiSet {
	return &MultiSet{
		data: make([]int, 0, capacity),
	}
}

func (m *MultiSet) lowerBound(value int) int {
	left, right := 0, len(m.data)
	for left < right {
		mid := (left + right) / 2
		if m.data[mid] < value {
			left = mid + 1
		} else {
			right = mid
		}
	}
	return left
}

func (m *MultiSet) Insert(value int) {
	pos := m.lowerBound(value)
	m.data = append(m.data, 0)
	copy(m.data[pos+1:], m.data[pos:])
	m.data[pos] = value
}

func (m *MultiSet) Show() {
	fmt.Println("[" + Join(m.data, ", ") + "]")
}

func (m *MultiSet) Contains(value int) bool {
	pos := m.lowerBound(value)
	return pos < len(m.data) && m.data[pos] == value
}

func (m *MultiSet) Erase(value int) {
	pos := m.lowerBound(value)
	if pos >= len(m.data) || m.data[pos] != value {
		fmt.Println("value not found")
		return
	}
	copy(m.data[pos:], m.data[pos+1:])
	m.data = m.data[:len(m.data)-1]
}

func (m *MultiSet) Count(value int) int {
	pos := m.lowerBound(value)
	count := 0
	for i := pos; i < len(m.data) && m.data[i] == value; i++ {
		count++
	}
	return count
}

func (m *MultiSet) Unique() int {
	if len(m.data) == 0 {
		return 0
	}
	count := 1
	for i := 1; i < len(m.data); i++ {
		if m.data[i] != m.data[i-1] {
			count++
		}
	}
	return count
}

func (m *MultiSet) Clear() {
	m.data = []int{}
}

func Join(slice []int, sep string) string {
	if len(slice) == 0 {
		return ""
	}
	result := fmt.Sprintf("%d", slice[0])
	for _, value := range slice[1:] {
		result += sep + fmt.Sprintf("%d", value)
	}
	return result
}

func main() {
	var line, cmd string
	scanner := bufio.NewScanner(os.Stdin)
	ms := NewMultiSet(0)

	for scanner.Scan() {
		fmt.Print("$")
		line = scanner.Text()
		args := strings.Fields(line)
		fmt.Println(line)

		if len(args) == 0 {
			continue
		}

		cmd = args[0]

		switch cmd {
		case "end":
			return

		case "init":
			value, _ := strconv.Atoi(args[1])
			ms = NewMultiSet(value)

		case "insert":
			for _, part := range args[1:] {
				value, _ := strconv.Atoi(part)
				ms.Insert(value)
			}

		case "show":
			ms.Show()

		case "erase":
			value, _ := strconv.Atoi(args[1])
			ms.Erase(value)

		case "contains":
			value, _ := strconv.Atoi(args[1])
			fmt.Println(ms.Contains(value))

		case "count":
			value, _ := strconv.Atoi(args[1])
			fmt.Println(ms.Count(value))

		case "unique":
			fmt.Println(ms.Unique())

		case "clear":
			ms.Clear()

		default:
			fmt.Println("fail: comando invalido")
		}
	}
}
